To solve the N-Puzzle problem using constraint programming with OR-Tools, we need to model the sequence of moves that transform the start state into the end state within the given number of steps. Each step involves moving the empty tile (0) to an adjacent tile (up, down, left, or right), swapping their positions.

Here's the Python code to model and solve this problem:

```python
import json
from ortools.sat.python import cp_model

def solve_n_puzzle(N, puzzle_start, puzzle_end):
    model = cp_model.CpModel()
    size = len(puzzle_start)

    # Create variables for each tile at each step
    tiles = {}
    for step in range(N + 1):
        for i in range(size):
            for j in range(size):
                tiles[(step, i, j)] = model.NewIntVar(0, size * size - 1, f'tile_step{step}_pos{i}{j}')

    # Initial state constraints
    for i in range(size):
        for j in range(size):
            model.Add(tiles[(0, i, j)] == puzzle_start[i][j])

    # Final state constraints
    for i in range(size):
        for j in range(size):
            model.Add(tiles[(N, i, j)] == puzzle_end[i][j])

    # Transition constraints between steps
    for step in range(N):
        # Find the position of the empty tile (0) in the current step
        empty_pos = []
        for i in range(size):
            for j in range(size):
                empty_pos.append((i, j, tiles[(step, i, j)] == 0))

        # The empty tile must be in exactly one position
        model.AddExactlyOne([cond for (i, j, cond) in empty_pos])

        # For each possible empty tile position, define possible moves
        for i in range(size):
            for j in range(size):
                # Current position is empty
                is_empty = tiles[(step, i, j)] == 0

                # Possible adjacent moves
                moves = []
                if i > 0:
                    moves.append((i - 1, j))  # Up
                if i < size - 1:
                    moves.append((i + 1, j))  # Down
                if j > 0:
                    moves.append((i, j - 1))  # Left
                if j < size - 1:
                    moves.append((i, j + 1))  # Right

                # For each possible move, create a transition
                for ni, nj in moves:
                    # The adjacent tile moves to the empty position
                    move_cond = model.NewBoolVar(f'move_step{step}_from{i}{j}_to{ni}{nj}')
                    model.Add(tiles[(step + 1, i, j)] == tiles[(step, ni, nj)]).OnlyEnforceIf(move_cond)
                    model.Add(tiles[(step + 1, ni, nj)] == 0).OnlyEnforceIf(move_cond)
                    model.Add(is_empty).OnlyEnforceIf(move_cond)

                    # Other tiles remain the same
                    for x in range(size):
                        for y in range(size):
                            if (x == i and y == j) or (x == ni and y == nj):
                                continue
                            model.Add(tiles[(step + 1, x, y)] == tiles[(step, x, y)]).OnlyEnforceIf(move_cond)

    # Solve the model
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        solution = []
        for step in range(N + 1):
            state = []
            for i in range(size):
                row = []
                for j in range(size):
                    row.append(solver.Value(tiles[(step, i, j)]))
                state.append(row)
            solution.append(state)
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")

# Input data
N = 20
puzzle_start = [
    [0, 3, 6],
    [2, 4, 8],
    [1, 7, 5]
]
puzzle_end = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 0]
]

solve_n_puzzle(N, puzzle_start, puzzle_end)
```

### Explanation:
1. **Variables**: We create variables for each tile at each step from 0 to N.
2. **Initial and Final States**: We enforce that the initial state matches `puzzle_start` and the final state matches `puzzle_end`.
3. **Transitions**: For each step, we ensure that the empty tile (0) moves to an adjacent position, swapping with the adjacent tile. All other tiles remain unchanged.
4. **Solving**: The solver finds a sequence of moves that transforms the start state to the end state in N steps. The solution is printed as a list of states at each step.

This approach models the N-Puzzle as a constraint satisfaction problem, ensuring that each move is valid and the solution is found within the given number of steps. The output is a JSON array of puzzle states at each step.

